// Live Google Drive input configuration. This folder is searched on every execution.
// Replace both placeholders with the folder IDs from your Drive URLs (/drive/folders/<ID>).
const cfg = {
  inputFolderId: 'REPLACE_WITH_INPUT_FOLDER_ID',

  // Audit policy rules (not sample input records).
  sodRules: [
    {
      id: 'SOD1',
      roles: ['Finance_Approver', 'Finance_Initiator'],
      description: 'Cannot initiate and approve payments'
    }
  ],

  outputFilePrefix: 'access-control-audit',
  outputFolderId: 'REPLACE_WITH_OUTPUT_FOLDER_ID'
};
return [{ json: cfg }];

// Validate the live Google Drive folder configuration.
// This node contains no A1-range parsing and only validates the folder configuration.
const incoming = $input.all();
if (!incoming.length || !incoming[0].json) {
  throw new Error('CONFIGURATION INPUT MISSING: connect this node directly after Audit Configuration and run the workflow from the beginning.');
}
const c = incoming[0].json;
const errors = [];
const folderId = String(c.inputFolderId ?? '').trim();
if (!folderId || folderId.startsWith('REPLACE_WITH_')) {
  errors.push('inputFolderId is not configured. Open Audit Configuration and paste the ID from your Google Drive INPUT folder URL.');
} else if (!/^[A-Za-z0-9_-]{10,}$/.test(folderId)) {
  errors.push('inputFolderId does not look like a valid Google Drive folder ID. Copy only the folder ID, not the full URL.');
}
if (!Array.isArray(c.sodRules) || c.sodRules.length === 0) {
  errors.push('sodRules must contain at least one audit rule.');
}
const outId = String(c.outputFolderId ?? '').trim();
if (!outId || outId.startsWith('REPLACE_WITH_')) {
  errors.push('outputFolderId is not configured. Paste the ID from your Google Drive OUTPUT folder URL.');
}
if (!String(c.outputFilePrefix ?? '').trim()) {
  errors.push('outputFilePrefix is required.');
}
if (errors.length) {
  throw new Error('CONFIGURATION VALIDATION FAILED: ' + errors.join(' | '));
}
return [{ json: c }];

