function normKey(value) {
  return String(value ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
}
function inputRows() {
  return $input.all().flatMap(item => {
    const j = item.json || {};
    if (Array.isArray(j.rows)) return j.rows;
    if (j.row && typeof j.row === 'object') return [j.row];
    return [j];
  });
}
function cell(row, aliases, index) {
  if (Array.isArray(row)) return row[index] ?? '';
  const entries = Object.entries(row || {});
  for (const alias of aliases) {
    const wanted = normKey(alias);
    const found = entries.find(([key]) => normKey(key) === wanted);
    if (found) return found[1] ?? '';
  }
  // Also support CSV parser output with numeric column keys.
  return row?.[String(index)] ?? '';
}
const rows = inputRows();
const seen = new Set();
const out = [];
for (const r of rows) {
  const user = String(cell(r, ['User', 'Email', 'User Email', 'Username', 'User Name', 'User ID', 'UPN', 'Account'], 0)).trim().toLowerCase();
  const role = String(cell(r, ['Role', 'Assigned Role', 'Access Role', 'Role Name'], 1)).trim();
  if (!user || !role) continue;
  const key = user + '|' + role.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  out.push({ user, role });
}
if (!out.length) {
  throw new Error('UserAccess.csv produced no usable records. Expected columns similar to User and Role, with a header row.');
}
return [{ json: { source: 'userAccess', rows: out } }];

