// Aggregate the actual users processed in this run and include an input-source manifest.
const items = $input.all();
if (!items.length) throw new Error('Final report received no completed user records.');
const users = items.map((item,index) => {
  const u = item.json;
  if (!u || !u.user) throw new Error(`Final report received an invalid user record at item ${index}.`);
  return { user: String(u.user), roles: Array.isArray(u.roles) ? u.roles : [], status: u.status ?? 'Unknown', violations: Array.isArray(u.violations) ? u.violations : [], inputSources: u.inputSources || {} };
});
const seenUsers = new Set();
for (const u of users) {
  if (seenUsers.has(u.user)) throw new Error(`Final report received duplicate completed user: ${u.user}`);
  seenUsers.add(u.user);
}
const violations = users.flatMap(u => u.violations);
const terminated_active = violations.filter(v => v.type === 'TerminatedActive').map(v => ({ user:v.user, roles:v.roles||[], explanation:v.explanation||'' }));
const role_mismatch = violations.filter(v => v.type === 'RoleMismatch').map(v => ({ user:v.user, roles:v.roles||[], missing_roles:v.missing_roles||[], explanation:v.explanation||'' }));
const sod_conflicts = violations.filter(v => v.type === 'SoDConflict').map(v => ({ user:v.user, conflicting_roles:v.conflicting_roles||[], rule_id:v.rule_id||'', description:v.description||'', explanation:v.explanation||'' }));
const summary = { processed_users:users.length, terminated_active:terminated_active.length, role_mismatch:role_mismatch.length, sod_conflicts:sod_conflicts.length, total_violations:violations.length };
const runTimestamp = new Date().toISOString();
const inputSources = users[0].inputSources || {};
const headers = ['RecordType','ViolationType','User','Roles','MissingRoles','ConflictingRoles','RuleID','Description','Explanation','Count','SourceFile','SourceFileId','SourceModifiedTime','SourceRecordCount','RunTimestamp'];
function csvEscape(value) {
  const text = Array.isArray(value) ? value.join('; ') : (value === null || value === undefined ? '' : String(value));
  return '"' + text.replace(/"/g, '""') + '"';
}
const rows = [headers];
for (const [sourceName, source] of Object.entries(inputSources)) {
  rows.push(['SOURCE','INPUT_FILE','','','','','',`Loaded ${sourceName} input`,'','',source.fileName,source.fileId,source.modifiedTime,source.parsedRecords,runTimestamp]);
}
for (const v of terminated_active) rows.push(['VIOLATION','TerminatedActive',v.user,v.roles,'','','','Terminated user still has active access',v.explanation,'','','','','',runTimestamp]);
for (const v of role_mismatch) rows.push(['VIOLATION','RoleMismatch',v.user,v.roles,v.missing_roles,'','','Assigned role is missing from RBAC matrix',v.explanation,'','','','','',runTimestamp]);
for (const v of sod_conflicts) rows.push(['VIOLATION','SoDConflict',v.user,'','',v.conflicting_roles,v.rule_id,v.description,v.explanation,'','','','','',runTimestamp]);
rows.push(['SUMMARY','PROCESSED_USERS','','','','','','Total users processed','',summary.processed_users,'','','','',runTimestamp]);
rows.push(['SUMMARY','TerminatedActive','','','','','','Total terminated users with active access','',summary.terminated_active,'','','','',runTimestamp]);
rows.push(['SUMMARY','RoleMismatch','','','','','','Total role assignments missing from RBAC matrix','',summary.role_mismatch,'','','','',runTimestamp]);
rows.push(['SUMMARY','SoDConflict','','','','','','Total segregation-of-duties conflicts','',summary.sod_conflicts,'','','','',runTimestamp]);
rows.push(['SUMMARY','TOTAL','','','','','','Total audit violations','',summary.total_violations,'','','','',runTimestamp]);
const csv_content = rows.map(row => row.map(csvEscape).join(',')).join('\r\n');
return [{ json: { csv_content, report: { users, terminated_active, role_mismatch, sod_conflicts, summary, inputSources, runTimestamp }, summary, inputSources, runTimestamp } }];

